StructuralRule.Predicate:
FunctionCall call:
   call.function is [Function f:
       f.name matches "put.*"
       and f.enclosingClass.name == "android.content.SharedPreferences$Editor"
   ]
   and call.arguments[0].constantValue matches "(?i).*pass(wd|word|phrase).*|.*token$|^ssn.*|.*ssn$|.social.*security.*|.*encrypt(?!ed).*|plaintext|cleartext|.*creditcard.*|.*card(num|no).*|.*cvv.*|.*pin$"
   and not call.enclosingClass contains [Function anyFunc:
       anyFunc contains [FunctionCall:
           possibleTargets contains [Function:
               name == "create"
               and enclosingClass.supers contains [Class:
                   name == "androidx.security.crypto.EncryptedSharedPreferences"
               ]
           ]
       ]
   ]

FunctionCall:
    possibleTargets contains [Function:
        (constructor or name == "init^")
        and enclosingClass.supers contains [Class:
            name == "androidx.credentials.CreatePasswordRequest"
        ]
    ]
    and arguments[1] is [Expression:
        constantValue == ""
    ]*

/* An Android Activity class */
Class: supers contains [Class: name is "android.app.Activity"] and
        /* ...that invokes the SQLiteOpenHelper class */
        contains [Function: reaches [Function:
            constructor and
            enclosingClass.name is "android.database.sqlite.SQLiteOpenHelper"]* ] and
        /* ...but does not have a stop/destroy method to properly close the connection */
        not contains [Function: name matches "on(Stop|Destroy)"]

/* Find the pause/stop/destroy callback */
Function: name matches "on(Pause|Stop|Destroy)" and
        /* ...of an Android Activity class */
        enclosingClass.supers contains [Class: name is "android.app.Activity"] and
        /* ...that invokes the SQLiteOpenHelper class */
        enclosingClass contains [Function: reaches [Function:
            constructor and
            enclosingClass.name is "android.database.sqlite.SQLiteOpenHelper"]* ] and
        /* ...but never invokes close() upon terminating the Activity */
        not reaches [Function:
            name is "close" and
            enclosingClass.name is "android.database.sqlite.SQLiteOpenHelper"]

/* An Android Activity class */
Class: supers contains [Class: name is "android.app.Activity"] and
        /* ...that constructs a media object */
        contains [Function: reaches [Function:
            (constructor or name is "create") and
            enclosingClass.name matches "android\.media\.(MediaRecorder|MediaPlayer|AudioRecord)"]* ] and
        /* ...but does not have a stop/destroy method to properly release the resource */
        not contains [Function: name matches "on(Stop|Destroy)"]

/* Find the pause/stop/destroy callback */
Function: name matches "on(Pause|Stop|Destroy)" and
        /* ...of an Android Activity class */
        enclosingClass.supers contains [Class: name is "android.app.Activity"] and
        /* ...that constructs a media object */
        enclosingClass contains [Function: reaches [Function:
            (constructor or name is "create") and
            enclosingClass.name matches "android\.media\.(MediaRecorder|MediaPlayer|AudioRecord)"]* ] and
        /* ...but never invokes release() upon terminating the Activity */
        not reaches [Function:
            name is "release" and
            enclosingClass.name matches "android\.media\.(MediaRecorder|MediaPlayer|AudioRecord)"]

StructuralRule.Script:
// The list of rules for methods whose permissions aren't in the manifest
var results = new Array();
var template = "\n\tcall.function is [Function: enclosingClass.supers contains [Class: name == \"CLASS_NAME\"] and name == \"FUNCTION_NAME\" and labels contains [Label: ]*] and call.arguments[ARGUMENT_NUMBER].constantValue == ARGUMENT_VALUE";
var namePredicate = "";

// run the script only if it is an Android app
if (JavaUtils.isAndroidApp()) {
    for (var methodName in program.android_map_apf_ors) {
        var methAndArg = program.android_map_apf_ors[methodName];
        for (var i = 0; i < methAndArg.length; i++) {
            var perms = methAndArg[i]["permissions"];
            var fulfilled = false;
            for (var p = 0; p < perms.length; p++) {
                var perm = perms[p];
                var values = perm.split(" or ");
                for (var v = 0; v < values.length; v++) {
                    if (doesManifestContain(values[v])) {
                        fulfilled = true;
                    }
                }
            }

            if (!fulfilled) {
                var thisResult = new Object();
                var dotIndex = methodName.lastIndexOf(".");
                thisResult.key = methodName;
                thisResult.className = methodName.substring(0,dotIndex);
                thisResult.functionName = methodName.substr(dotIndex+1);
                thisResult.argumentNumber = methAndArg[i]["argument_number"];
                thisResult.argumentValue = methAndArg[i]["argument_value"];
                results.push(thisResult);
            }
        }
    }

    for each (var i in results) {
        if (namePredicate != "") {
            namePredicate += " or ";
        }
        namePredicate += template;
        namePredicate = namePredicate.replace(/CLASS_NAME/, i.className);
        namePredicate = namePredicate.replace(/FUNCTION_NAME/, i.functionName);
        namePredicate = namePredicate.replace(/ARGUMENT_NUMBER/, i.argumentNumber);
        namePredicate = namePredicate.replace(/ARGUMENT_VALUE/, i.argumentValue);
    }
}

if (0 == results.length) {
    delete rule;
}else{
    namePredicate = 'FunctionCall call: ' + namePredicate
    rule.Predicate = String(namePredicate);
}

var template = "\n\tcall.function is [Function: enclosingClass.supers contains [Class: name == \"CLASS_NAME\"] and name == \"FUNCTION_NAME\" and labels contains [Label: ]*]";
var results = new Array();

// create predicate fragment
var namePredicate = "";

// run the script only if it is an Android app
if (JavaUtils.isAndroidApp()) {
    for (var methodName in program.android_map_apf) {
        var perms = program.android_map_apf[methodName];
        var fulfilled = false;
        var disallow = false;
        for (var p = 0; p < perms.length; p++) {
            var perm = perms[p];
            if (doesManifestContain(perm)) {
                fulfilled = true;
            } else {
                disallow = true;
                fulfilled = false;
            }
        }

        if (!fulfilled || disallow) {
            var thisResult = new Object();
            var dotIndex = methodName.lastIndexOf(".");
            thisResult.key = methodName;
            thisResult.className = methodName.substring(0,dotIndex);
            thisResult.functionName = methodName.substr(dotIndex+1);
            results.push(thisResult);
        }
    }

    for each (var i in results) {
        if (namePredicate != "") {
            namePredicate += " or ";
        }
        namePredicate += template;
        namePredicate = namePredicate.replace(/CLASS_NAME/, i.className);
        namePredicate = namePredicate.replace(/FUNCTION_NAME/, i.functionName);
    }
}

if (0 == results.length) {
    delete rule;
}else{
    namePredicate = 'FunctionCall call: ' + namePredicate
    rule.Predicate = String(namePredicate);
}

    var template = "\n\tcall.function is [Function: enclosingClass.supers contains [Class: name == \"CLASS_NAME\"] and name == \"FUNCTION_NAME\" and labels contains [Label: ]*]";
    var results = new Array();

    // create predicate fragment
    var namePredicate = "";

   // run the script only if it is an Android app
   if (JavaUtils.isAndroidApp()) {
     for (var methodName in program.android_map_or_simple) {
           var perms = program.android_map_or_simple[methodName];
           var fulfilled = false;
           var disallow = false;
           for (var p = 0; p < perms.length; p++) {
                   var perm = perms[p];
                   var values = perm.split(" or ");
                   var found = false;
                   for (var v = 0; v < values.length; v++) {
                           if (doesManifestContain(values[v])) {
                                   found = true;
                                   break;
                           }
                   }
                   if (found) {
                           fulfilled = true;
                           //alert("FULFILLED: " + methodName);
                   } else {
                           //alert("UNFULFILLED: " + methodName);
                           disallow = true;
                           fulfilled = false;
                   }
           }

           if (!fulfilled || disallow) {
                   var thisResult = new Object();
                   var dotIndex = methodName.lastIndexOf(".");
                   thisResult.key = methodName;
                   thisResult.className = methodName.substring(0,dotIndex);
                   thisResult.functionName = methodName.substr(dotIndex+1);
                   results.push(thisResult);
           }
     }


  for each (var i in results) {
    if (namePredicate != "") {
      namePredicate += " or ";
    }
    namePredicate += template;
    namePredicate = namePredicate.replace(/CLASS_NAME/, i.className);
    namePredicate = namePredicate.replace(/FUNCTION_NAME/, i.functionName);
  }
}

if (0 == results.length) {
  delete rule;
}else{
  namePredicate = 'FunctionCall call: ' + namePredicate;
  rule.Predicate = String(namePredicate);
}

StructuralRule.Predicate:
Class:
    functions contains [Function:
        name == "onReceivedSslError"
        and enclosingClass.supers contains [Class:
            name == "android.webkit.WebViewClient"
        ]
        and reaches [Function:
            contains [FunctionCall:
                possibleTargets contains [Function:
                    name == "proceed"
                    and enclosingClass.supers contains [Class:
                        name == "android.webkit.SslErrorHandler"
                    ]
                ]
            ]
        ]
        and not reaches [Function:
            contains [FunctionCall:
                possibleTargets contains [Function:
                    name == "cancel"
                    and enclosingClass.supers contains [Class:
                        name == "android.webkit.SslErrorHandler"
                    ]
                ]
            ]
        ]
    ]

StructuralRule.Script:
var namePredicate = "";
if (JavaUtils.isAndroidApp()) {
    namePredicate = "";
    if (program.android_exported_activities !== null && program.android_exported_activities.length > 0) {
        for each (var a in program.android_exported_activities) {
            if (namePredicate != "") namePredicate += " or ";
            namePredicate += " name == \"" + String(a) + "\"\n";
        }
    }
}

if (namePredicate){
    predicate = "Class exportedActivity: (" + namePredicate + ") and "
    rule.Predicate = String(rule.Predicate).replace(/Class exportedActivity:/g, predicate);
}else{
    delete rule;
}

StructuralRule.Predicate:
Class exportedActivity: /* TEMPLATED */
    supers contains [Class:
        name == "android.preference.PreferenceActivity"
    ]
    and (
        /* since it must be implemented, it indicates its a pre-KitKat app */
        not functions contains [Function:
            name == "isValidFragment"
        ]
        /* function always returns true in at least one path. No whitelisting is applied */
        or functions contains [Function:
            name == "isValidFragment"
            and contains [ReturnStatement:
                /* see bug 57773 */
                expression.constantValue is [Boolean: is true]
                or expression is [VariableAccess:
                    variable is [Variable:
                        uses contains [VariableAccess va:
                            enclosingStatement is [AssignmentStatement:
                                lhs is [VariableAccess va2: va2 is va]
                                and rhs.constantValues contains [Boolean: is true]
                            ]
                        ]
                    ]
                ]
            ]
        ]
    )

FunctionCall fc:
    function is [Function:
        (name == "init^" or constructor)
        and enclosingClass is [Class:
            name == "android.os.StrictMode.ThreadPolicy.Builder"
        ]
    ]
    or function is [Function:
        name == "forName"
        and enclosingClass.supers contains [Class:
            name == "java.lang.Class"
        ]
        and fc.arguments[0].constantValue == "android.os.StrictMode"
    ]

