    possibleTargets contains [Function:
        (constructor or name == "init^")
        and enclosingClass.supers contains [Class:
            name == "androidx.credentials.CredentialManagerCallback"
        ]
    ]
    and instance is [Expression callback:
        type.definition contains [Function onResult: name == "onResult"]
    ]

FunctionCall:
    possibleTargets contains [Function:
        (constructor or name == "init^")
        and enclosingClass.supers contains [Class:
            name == "androidx.credentials.CredentialManagerCallback"
        ]
    ]
    and instance is [Expression callback:
        type.definition contains [Function onResult:
            name == "onResult"
            and parameters[0] is [Variable result:
                type.definition.supers contains [Class:
                    name matches "androidx\.credentials\.(Get|Create)CredentialResponse"
                ]
            ]
        ]
    ]

FunctionCall fc:
    function is [Function:
        name == "forEach"
        and enclosingClass.supers contains [Class:
            name == "androidx.core.util.LongSparseArrayKt"
        ]
    ]
    and arguments[0] is [Expression arr:]
    and arguments[1] is [Expression lambda:]
    and enclosingStatement is [Statement closure:]


FunctionCall fc: fc.function is [Function f:
