    and f.enclosingClass.supers contains [Class c:
            name matches "(androidx\.collection|android\.util)\.ArraySet"
        ]
    ]
    and fc.instance is [Expression this: ]
    and arguments[0] is [Expression arg0:
        not arg0.type.name matches "int|long|float"
    ]

