CharacterizationRule.Script:
var classNamePredicate = '';
var defaultClassNamePredicate = 'Class components: name == ""';
function appendClassNames(exportedComponents) {
    for each (var a in (exportedComponents || [])) {
        if (classNamePredicate != '') classNamePredicate += ' or ';
        classNamePredicate += ' name == "' + String(a) + '"\n';
    }
}
appendClassNames(program.android_exported_activities);
appendClassNames(program.android_exported_receivers);
appendClassNames(program.android_exported_services);
if (classNamePredicate){
    classNamePredicate = 'Class components: ' + classNamePredicate
}
rule.StructuralMatch = String(rule.StructuralMatch).replace(/Class components: /g, (classNamePredicate || defaultClassNamePredicate));

CharacterizationRule.Notes:
Adds NESTED_INTENT taint when Android ICC method called with an Intent argument that is either:
    a) the return value of a getParcelable* function call:
       startActivity((Intent) getIntent().getParcelableExtra("intent"));

    b) a Parcelable type casted to an Intent:
       Parcelable p = getIntent().getParcelableExtra("intent");
       startActivity((Intent) p);

Adds NESTED_INTENT taint on the lhs of an assignment where the lhs type is an Intent and either:
    a) the rhs is the return value of a Bundle|Intent|List function call returning a type
       that can be casted to an Intent:
       Intent i = (Intent) getIntent().getParcelableExtra("intent");
       Intent i = (Intent) getIntent().getExtras().getParcelable("intent");
       Intent i = (Intent) getIntent().getParcelableArrayListExtra("intent").get(0);

    b) the rhs is a Parcelable type:
       Parcelable p = getIntent().getParcelableExtra("intent");
       Intent i = (Intent) p;

       Parcelable[] p = getIntent().getParcelableArrayExtra("intent");
       Intent i = (Intent) p[0];

CharacterizationRule.StructuralMatch:
AssignmentStatement stmt:
    stmt.lhs is [VariableAccess va: 
        type.definition is [Class c: supers contains [Class super: super.type.name == "android.content.Intent"]]
    ]
    and (
        stmt.rhs is [FunctionCall: 
            not function.returnType is [Type: definition.supers contains [Class: name == "android.content.Intent"]]
            and instance is [Expression:
                type.definition is [Class: 
                    supers contains [Class: 
                        name == "android.os.Bundle"
                        or name == "android.content.Intent"
                        or name == "java.util.List"
                        or name == "kotlin.collections.List"
                    ]
                ]
            ]
        ]
        or stmt.rhs is [VariableAccess:
            variable.type.definition is [Class: name == "android.os.Parcelable"]
        ]
        or stmt.rhs is [ArrayAccess:
            base.type.definition is [Class: name == "android.os.Parcelable"]
        ]
    )

CharacterizationRule.Script:
var namePredicate = "";
if (program.android_callbacks !== null && program.android_callbacks.length > 0) {
    for each(var cb in program.android_callbacks) {
        if (namePredicate != "") namePredicate += " or ";
        cb = String(cb);
        if (cb.indexOf("$") > -1)
            namePredicate += " name matches \"" + String(cb) + "\"\n";
        else
            namePredicate += " name == \"" + String(cb) + "\"\n";
    }
}

if (namePredicate){
    predicate = "Class callbacks:" + namePredicate
    rule.StructuralMatch = String(rule.StructuralMatch).replace(/Class callbacks:/g, predicate);
}else{
    delete rule;
}

