FunctionCall call: call.function is
    [Function f:
            /* look for a function whose name is not asBinder and */
            f.name != "asBinder" and
            /* whose enclosing class implements an interface that */
            f.enclosingClass.supers contains [Class c: c.directSupers contains
                    /*  directly extends "android.os.IInterface", and */
                    [Class c2: c2.name == "android.os.IInterface"] and
                    /* the function we are looking for implements one of the functions in the interface */
                    c.functions contains [Function f2: f2 in f.supers]]
     ]

Function f:
            /* look for a function whose name is not asBinder and */
            f.name != "asBinder" and
            /* whose enclosing class implements an interface that */
            f.enclosingClass.supers contains [Class c: c.directSupers contains
                    /*  directly extends "android.os.IInterface", and */
                    [Class c2: c2.name == "android.os.IInterface"] and
