CharacterizationRule.Notes:
See: https://developer.android.com/guide/components/bound-services#Messenger

Intended coding pattern:

public class MessengerService extends Service {
    /**
    * Handler of incoming messages from clients.
    */
    class IncomingHandler extends Handler {
        @Override
        public void handleMessage(Message msg) {
            sink(msg)
        }
    }
}

See: https://developer.android.com/guide/components/bound-services#Binder

Intended coding pattern:

public class LocalService extends Service {
// Binder given to clients
private final IBinder binder = new LocalBinder();

public class LocalBinder extends Binder {
    LocalService getService() {
        // Return this instance of LocalService so clients can call public methods
        return LocalService.this;
    }
}

@Override
public IBinder onBind(Intent intent) {
    return binder;
}

/* Each implementation can have an arbitrary number of functions */
/* method for clients */
public void logForge(int i){
    // [Ruletest] Some Sink
    sink("LocalService", s);
}

See: https://developer.android.com/guide/components/bound-services#Binder

Intended coding pattern:

public class LocalService extends Service {
// Binder given to clients
private final IBinder binder = new LocalBinder();

public class LocalBinder extends Binder {
    LocalService getService() {
        // Return this instance of LocalService so clients can call public methods
        return LocalService.this;
    }
}

@Override
public IBinder onBind(Intent intent) {
    return binder;
}

/** method for clients */
public void logForge(String s){
    // [Ruletest] Log Forging
    Log.i("LocalService", s);
}

DataflowSourceRule.Script:
 var pattern = "";

 function escapeRegExp(str) {
     return str.replace(/[\-\[\]\/\{\}\(\)\*\+\?\.\\\^\$\|]/g, "\\$&");
 }

 if (JavaUtils.isAndroidApp()) {
     for (var key in program.android_metadata) {
         var metadata_values = program.android_metadata[key];
         if (metadata_values === null || metadata_values === undefined)
             continue;

         for (var i in metadata_values) {
             var metadata = metadata_values[i];
             if (metadata.value == "null"
                 || metadata.value == "undefined"
                 || metadata.value.match(/^(http|ftp)s:/i) === null
                 || metadata.value.match(/^(http|ftp)s:/i) === undefined
                 || metadata.value.match(/^(http|ftp)s:/i).length == 0)
                     continue;

             if (pattern != "") pattern += "|";
             pattern += escapeRegExp(String(metadata.name));
         }
     }
}

if (pattern == "") pattern = "FORTIFY_NON_EXISTANT";
rule.Conditional.ConstantMatches.Pattern = pattern;

