ControlflowRule.Definition:
state start (start);
state opened : "statedesc.java.resource.dbcursor.acquired";
state check_if_closed;
state closed : "statedesc.java.resource.db.released";
state error (error) : "statedesc.java.resource.db.leaked";

var cursor;
var isClosed;

start -> opened { cursor = $getCursor1(...) | cursor = $getCursor2(...) }

opened -> check_if_closed { ~isClosed = @cursor.isClosed() }
opened -> closed { #ifblock(@cursor, null, true) | @cursor.$close() | $openPipeHelper(?, ?, ?, cursor, ...) | @Escape(cursor -> escapeArg) | #escape(cursor) }
opened -> error { #end_scope(cursor) }

check_if_closed -> opened { #ifblock(@isClosed, true, false) }
check_if_closed -> closed { #ifblock(@isClosed, true, true) | #ifblock(@cursor, null, true) | @cursor.$close() | $openPipeHelper(?, ?, ?, cursor, ...) | @Escape(cursor -> escapeArg) | #escape(cursor) }
check_if_closed -> error { #end_scope(cursor) }

state start (start);
state opened : "statedesc.java.resource.dbconnection.acquired";
state check_if_open;
state closed : "statedesc.java.resource.db.released";
state error (error) : "statedesc.java.resource.db.leaked";

var db;
var isOpen;

start -> opened { db = $openDB(...) }

opened -> check_if_open { ~isOpen = @db.isOpen() }
opened -> closed { #ifblock(@db, null, true) | @db.$close() | @Escape(db -> escapeArg) | #escape(db) }
opened -> error { #end_scope(db) }

check_if_open -> opened { #ifblock(@isOpen, true, true) }
check_if_open -> closed { #ifblock(@isOpen, true, false) | #ifblock(@db, null, true) | @db.$close() | @Escape(db -> escapeArg) | #escape(db)}
check_if_open -> error { #end_scope(db) }

state start (start);
state accessed : "statedesc.java.nullreturn.mayReturnNull";
state checked;
state used (error) : "statedesc.java.nullreturn.used";
var p;

start -> accessed { p = $getAction(...) | p = $getExtra(...) | p = $bget(...) }
accessed -> checked { #ifblock(p, null, false) }
accessed -> used { p.$any(...) }

state init (start);
state settings_loaded;
state javascript_enabled;
state universal_access_enabled;
state both_enabled;
state insecure_load (error);

var view;
var settings;

init -> settings_loaded { settings = view.$getSettings() }
settings_loaded -> javascript_enabled { settings.$setJavascript(...) }
settings_loaded -> universal_access_enabled { settings.$setUniversalAccess(...) }
javascript_enabled -> both_enabled { settings.$setUniversalAccess(...) }
universal_access_enabled -> both_enabled { settings.$setJavascript(...) }
both_enabled -> insecure_load { view.$load(...) }

state init (start);
state settings_loaded;
state javascript_enabled;
state insecure_load (error);

var view;
var settings;

init -> settings_loaded { settings = view.$getSettings() }
settings_loaded -> javascript_enabled { settings.$setJavascript(...) }
javascript_enabled -> insecure_load { view.$load(...) }

state start (start);
state released;
state reacquired;
state nullchecked;
state dereferenced (error);
var r;

start -> released   { r.$release() }
released -> reacquired   { r = $reacquire(...) }
released -> nullchecked   { #ifblock(r, null, true) }
released -> dereferenced   { r.$dereference(...) }

state start (start);
state released;
state reacquired;
state nullchecked;
state dereferenced (error);
var r;

start -> released   { r.$release() }
released -> reacquired   { r = $reacquire(...) }
released -> nullchecked   { #ifblock(r, null, true) }
released -> dereferenced   { r.$dereference(...) }

state start (start);
state released;
state reacquired;
state nullchecked;
state dereferenced (error);
var r;

start -> released   { r.$release() }
released -> reacquired   { r = $reacquire(...) | r = $reconstruct(...) }
released -> nullchecked   { #ifblock(r, null, true) }
released -> dereferenced   { r.$dereference(...) }

state start (start);
state initialized;
state released;
state error (error);

var c;

start-> initialized {c = $open()}
initialized -> released {c.$release()}
initialized -> error {#end_scope(c)}

state start (start);
state broad_target;
state error (error);

var t;

start-> broad_target {t = $parse(...)}
broad_target -> error { $post(?,t) }

state start (start);
state loaded : "statedesc.java.resource.acquired";
state released;
state end_of_scope (error) : "statedesc.java.resource.leaked";
var r;
var r_isClosed;

start -> loaded { 
    r = $accept() | 
    r.$connect(...) 
}

loaded -> loaded { r_isClosed = r.$isSocketClosed() }

loaded -> released { 
    r.$close() | 
    #ifblock(r, null, true) | 
    #ifblock(@r_isClosed == true, true) | 
    #ifblock(@r_isClosed == false, false) |
    @Escape(r -> escapeArg) |
    #escape(r)
}

loaded -> end_of_scope { #end_scope(r) }

state start (start);
state loaded : "statedesc.java.resource.acquired";
state released;
state end_of_scope (error) : "statedesc.java.resource.leaked";
var r;

start -> loaded {
    r.$ServerInit(...)
}

loaded -> released { 
    #ifblock(r, null, true) | 
    @Escape(r -> escapeArg) |
    #escape(r) |
    r.$close()
}

loaded -> end_of_scope { #end_scope(r) }

state start (start);
state impIntent : "statedesc.android.implicitintent";
state remediate;
state pendingIntent (error) : "statedesc.android.pendingintent";

var impInt;

start -> impIntent {impInt = $implicit_intent(...) | impInt.$implicit_intent(...)}

impIntent -> remediate { impInt.$setComponent(...) | impInt.$setClass(...) | impInt.$setPackage(...)} 
impIntent -> pendingIntent {$pending_intent(...,impInt,...)}

state start (start);
state impIntent : "statedesc.android.implicitintent";
state remediate;
state consumeIntent (error) : "statedesc.android.consume";
state end_of_scope;

var imp;

start -> impIntent {imp = $implicit_intent(...) | imp.$implicit_intent(...)}
impIntent -> remediate { imp.$setComponent(...) | imp.$setClass(...) | imp.$setPackage(...)} 
impIntent -> consumeIntent {$consume(...,imp,...)}

